#include "sl.h"

#include <cstdio>
#include <cstring>
#include <filesystem>
#include <string>

namespace
{
    // A square pyramid as Wavefront OBJ text; normals are generated by the loader.
    const char *pyramid_obj =
        "v -0.5 0 -0.5\nv 0.5 0 -0.5\nv 0.5 0 0.5\nv -0.5 0 0.5\nv 0 1 0\n"
        "vt 0 0\nvt 1 0\nvt 0.5 1\n"
        "f 1/1 2/2 5/3\nf 2/1 3/2 5/3\nf 3/1 4/2 5/3\nf 4/1 1/2 5/3\nf 4 3 2 1\n";

    // Models live in assets/models; look relative to the working directory and its parent.
    std::string model_path(const char *name)
    {
        for (const char *root : {"assets/models/", "../assets/models/"})
            if (std::filesystem::exists(std::string(root) + name))
                return std::string(root) + name;
        return std::string("assets/models/") + name;
    }

    sl::Bitmap *make_checker(int size, int cell)
    {
        sl::Bitmap *bitmap = sl::create_bitmap(size, size);
        if (!bitmap)
            return nullptr;
        bitmap->pixels.resize(static_cast<std::size_t>(size) * size * 4);
        for (int y = 0; y < size; ++y)
            for (int x = 0; x < size; ++x)
            {
                const bool light = ((x / cell) + (y / cell)) % 2 == 0;
                std::uint8_t *pixel = &bitmap->pixels[(static_cast<std::size_t>(y) * size + x) * 4];
                pixel[0] = pixel[1] = pixel[2] = light ? 255 : 90;
                pixel[3] = 255;
            }
        bitmap->ram_dirty = true;
        return bitmap;
    }
}

int main(int argc, char *argv[])
{
    if (!sl::configure_graphics_backend_from_args(argc, argv))
        return -1;
    if (!sl::set_gfx_mode(sl::GFX_AUTODETECT_WINDOWED, 800, 600))
        return -1;

    sl::Surface3D *surface = sl::create_surface_3d(640, 480, 4);
    sl::Mesh *cube = sl::create_cube_mesh(1.0f, {240, 120, 80});
    sl::Mesh *sphere = sl::create_sphere_mesh(0.5f, 32, 16, {90, 170, 255});
    sl::Mesh *pyramid = sl::load_obj_mesh_from_memory(pyramid_obj, std::strlen(pyramid_obj), {255, 220, 90});
    sl::Bitmap *checker = make_checker(64, 8);
    sl::Mesh *plane = sl::create_plane_mesh(8.0f, 8.0f, {120, 130, 120});
    sl::Model *crate = sl::load_model(model_path("crate.obj"));
    sl::Model *gems = sl::load_model(model_path("gem.gltf"));
    sl::Model *box = sl::load_model(model_path("box.glb"));
    if (!crate || !gems || !box)
        std::fprintf(stderr, "Model load failed: %s\n", sl::last_error().c_str());
    if (!surface || !cube || !sphere || !plane || !pyramid || !checker)
    {
        std::fprintf(stderr, "3D surface unavailable on this backend.\n");
        sl::destroy_mesh(cube);
        sl::destroy_mesh(sphere);
        sl::destroy_mesh(plane);
        sl::destroy_surface_3d(surface);
        sl::shutdown();
        return -1;
    }

    sl::Camera camera;
    camera.position = {2.5f, 2.2f, 4.0f};
    camera.target = {0.0f, 0.3f, 0.0f};
    sl::set_light_3d({{-0.4f, -1.0f, -0.6f}, 0.25f});

    bool running = true;
    int frame_count = 0;
    while (running)
    {
        sl::Event event;
        while (sl::poll_event(&event))
        {
            if (event.type() == sl::Event::Type::quit ||
                (event.type() == sl::Event::Type::key_down && event.key() == sl::Event::Key::escape))
                running = false;
            sl::display_handle_event(event);
        }

        const float time = static_cast<float>(sl::time_ms()) * 0.001f;
        if (sl::begin_surface_3d(surface, camera))
        {
            sl::clear_surface_3d({20, 30, 60});
            sl::draw_mesh(plane, sl::model_matrix({0, -0.51f, 0}, {0, 0, 0}), {{255, 255, 255}, true, checker});
            sl::draw_mesh(pyramid, sl::model_matrix({0.0f, -0.5f, -1.2f}, {0, time * 0.5f, 0}), {{255, 255, 255}, true, nullptr});
            sl::draw_mesh(cube, sl::model_matrix({-0.8f, 0, 0}, {time * 0.7f, time, 0}), {{255, 255, 255}, true, checker});
            sl::draw_mesh(sphere, sl::model_matrix({0.9f, 0, 0}, {0, 0, 0}), {{255, 255, 255}, true});
            if (crate)
                sl::draw_model(crate, sl::model_matrix({-2.2f, 0.0f, -1.0f}, {0, time * 0.4f, 0}));
            if (box)
                sl::draw_model(box, sl::model_matrix({2.2f, 0.0f, -1.0f}, {0, -time * 0.4f, 0}));
            if (gems)
                sl::draw_model(gems, sl::model_matrix({0.0f, 0.4f, -2.8f}, {0, time * 0.6f, 0}));

            // 2D HUD drawn directly into the multisampled 3D surface
            sl::rectfill(sl::surface_3d_bitmap(surface), 16.0f, 16.0f, 250.0f, 68.0f, {15, 20, 35, 200});
            sl::rect(sl::surface_3d_bitmap(surface), 16.0f, 16.0f, 250.0f, 68.0f, {80, 160, 240, 255}, 1.5f);
            sl::gprintf(26, 24, {255, 255, 255}, "MSAA %dx Surface3D", sl::surface_3d_samples(surface));
            sl::gprintf(26, 42, {160, 200, 255}, "2D HUD on %s",
                        sl::graphics_backend() == sl::GraphicsBackend::vulkan ? "Vulkan" : "OpenGL");

            sl::end_surface_3d();
        }

        sl::clear_to_colour(sl::screen, {40, 40, 40});
        sl::draw_sprite(sl::surface_3d_bitmap(surface), 80, 60);
        sl::gprintf_center(32, {232, 236, 244}, "Surface3D example - Escape to exit");
        sl::show_video_bitmap();
        sl::end_frame();

        ++frame_count;
        const char *screenshot_env = std::getenv("RSIMLIB_SCREENSHOT");
        if (screenshot_env && frame_count == 10)
        {
            sl::save_bitmap(sl::screen, screenshot_env);
        }
        const char *frames_env = std::getenv("RSIMLIB_FRAMES");
        if (frames_env && frame_count >= std::atoi(frames_env))
        {
            running = false;
        }
    }

    sl::wait_for_graphics();
    sl::destroy_mesh(cube);
    sl::destroy_mesh(sphere);
    sl::destroy_mesh(plane);
    sl::destroy_mesh(pyramid);
    sl::destroy_model(crate);
    sl::destroy_model(gems);
    sl::destroy_model(box);
    sl::destroy_bitmap(checker);
    sl::destroy_surface_3d(surface);
    sl::shutdown();
    return 0;
}
